import crypto from "node:crypto";
import type { ModelDefinitionConfig } from "../config/types.models.js";

export interface DeepSeekPowChallenge {
  algorithm: string;
  challenge: string;
  difficulty: number;
  salt: string;
  signature: string;
  expire_at?: number; // Added for DeepSeekHashV1
}

// SHA3 WASM module embedded as base64 for portability
const SHA3_WASM_B64 =
  "";

export interface DeepSeekChatSession {
  biz_id: string;
  chat_session_id: string;
  title: string;
  id?: string;
}

export interface DeepSeekWebClientOptions {
  cookie: string;
  bearer?: string;
  userAgent?: string;
}

interface DeepSeekWasmExports extends WebAssembly.Exports {
  memory: WebAssembly.Memory;
  __wbindgen_export_0: (a: number, b: number) => number;
  __wbindgen_add_to_stack_pointer: (a: number) => number;
  wasm_solve: (
    retptr: number,
    ptrC: number,
    lenC: number,
    ptrP: number,
    lenP: number,
    difficulty: number,
  ) => void;
}

interface DeepSeekPowResponse {
  data?: {
    biz_data?: {
      challenge?: DeepSeekPowChallenge;
    };
    challenge?: DeepSeekPowChallenge;
  };
  challenge?: DeepSeekPowChallenge;
}

interface DeepSeekChatSessionBizData extends Partial<DeepSeekChatSession> {
  chat_session?: Partial<DeepSeekChatSession>;
  ttl_seconds?: number;
}

interface DeepSeekChatSessionResponse extends DeepSeekChatSessionBizData {
  code?: number;
  msg?: string;
  data?: {
    biz_code?: number;
    biz_msg?: string;
    biz_data?: DeepSeekChatSessionBizData;
  } & DeepSeekChatSessionBizData;
}

interface DeepSeekClientSettingsResponse {
  code?: number;
  data?: {
    biz_code?: number;
    biz_data?: {
      settings?: Record<string, { value?: unknown }>;
      version?: number;
    };
  };
}

interface DeepSeekRemoteModelConfig {
  model_type?: string;
  name?: string;
  description?: string;
  enabled?: boolean;
  switchable?: boolean;
  is_default?: boolean;
  input_character_limit?: number;
  search_feature?: unknown;
  file_feature?: {
    token_limit?: number;
    token_limit_with_thinking?: number;
    vision?: boolean;
  } | null;
}

type DeepSeekWebModelType = "default" | "expert" | "vision";

export function resolveDeepSeekWebModelType(model?: string): DeepSeekWebModelType {
  const normalized = (model || "").toLowerCase();
  if (normalized.includes("vision")) {
    return "vision";
  }
  return normalized.includes("expert") ? "expert" : "default";
}

export function resolveDeepSeekWebThinkingEnabled(model?: string): boolean {
  const normalized = (model || "").toLowerCase();
  return (
    normalized.includes("reasoner") ||
    normalized.includes("thinking") ||
    normalized.includes("deep-think") ||
    normalized.includes("r1")
  );
}

export function resolveDeepSeekWebSearchEnabled(model?: string, explicit?: boolean): boolean {
  if (typeof explicit === "boolean") {
    return explicit;
  }
  const normalized = (model || "").toLowerCase();
  return normalized.endsWith("-search") || normalized.includes("-search-");
}

function isObjectRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function sanitizeDeepSeekModelType(modelType: string): string {
  const normalized = modelType
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return normalized || "default";
}

function deepSeekModelIdForType(modelType: string): string {
  switch (modelType) {
    case "default":
      return "deepseek-chat";
    case "expert":
      return "deepseek-chat-expert";
    case "vision":
      return "deepseek-vision";
    default:
      return `deepseek-${sanitizeDeepSeekModelType(modelType)}`;
  }
}

function deepSeekReasonerModelIdForType(modelType: string): string {
  switch (modelType) {
    case "default":
      return "deepseek-reasoner";
    case "expert":
      return "deepseek-reasoner-expert";
    case "vision":
      return "deepseek-reasoner-vision";
    default:
      return `deepseek-reasoner-${sanitizeDeepSeekModelType(modelType)}`;
  }
}

function toDeepSeekRemoteModelConfig(value: unknown): DeepSeekRemoteModelConfig | null {
  if (!isObjectRecord(value)) {
    return null;
  }
  const modelType = typeof value.model_type === "string" ? value.model_type : undefined;
  if (!modelType) {
    return null;
  }
  return value as unknown as DeepSeekRemoteModelConfig;
}

function unwrapDeepSeekSettings(settings: Record<string, { value?: unknown }> | undefined) {
  const unwrapped: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(settings || {})) {
    unwrapped[key] = isObjectRecord(entry) && "value" in entry ? entry.value : entry;
  }
  return unwrapped;
}

function createDeepSeekWebModel(config: {
  id: string;
  name: string;
  reasoning: boolean;
  input?: Array<"text" | "image">;
  contextWindow?: number;
}): ModelDefinitionConfig {
  return {
    id: config.id,
    name: config.name,
    reasoning: config.reasoning,
    input: config.input || ["text", "image"],
    cost: {
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0,
    },
    contextWindow: config.contextWindow || 64000,
    maxTokens: 4096,
  };
}

function buildDeepSeekModelsFromRemoteConfigs(
  configs: DeepSeekRemoteModelConfig[],
): ModelDefinitionConfig[] {
  const baseEntries: Array<{
    model: ModelDefinitionConfig;
    searchSupported: boolean;
  }> = [];
  const seen = new Set<string>();
  for (const config of configs) {
    if (config.enabled === false || config.switchable === false || !config.model_type) {
      continue;
    }
    const modelType = config.model_type;
    const baseId = deepSeekModelIdForType(modelType);
    if (seen.has(baseId)) {
      continue;
    }
    seen.add(baseId);
    const baseName = config.name || `DeepSeek ${modelType}`;
    const contextWindow =
      config.input_character_limit ||
      config.file_feature?.token_limit ||
      config.file_feature?.token_limit_with_thinking ||
      64000;
    const input: Array<"text" | "image"> = config.file_feature ? ["text", "image"] : ["text"];
    const searchSupported = config.search_feature !== null;
    baseEntries.push({
      model: createDeepSeekWebModel({
        id: baseId,
        name: baseName,
        reasoning: false,
        input,
        contextWindow,
      }),
      searchSupported,
    });
    baseEntries.push({
      model: createDeepSeekWebModel({
        id: deepSeekReasonerModelIdForType(modelType),
        name: `${baseName} + Deep Thinking`,
        reasoning: true,
        input,
        contextWindow: config.file_feature?.token_limit_with_thinking || contextWindow,
      }),
      searchSupported,
    });
  }

  const models = baseEntries.map((entry) => entry.model);
  for (const { model, searchSupported } of baseEntries) {
    if (!searchSupported) {
      continue;
    }
    models.push({
      ...model,
      id: `${model.id}-search`,
      name: `${model.name} (Search)`,
    });
  }
  return models;
}

export class DeepSeekWebClient {
  private cookie: string;
  private bearer: string;
  private userAgent: string;
  private deviceId: string = "";

  constructor(options: DeepSeekWebClientOptions | string) {
    let finalOptions: DeepSeekWebClientOptions;
    if (typeof options === "string") {
      try {
        finalOptions = JSON.parse(options);
        if (typeof finalOptions === "string") {
          finalOptions = { cookie: finalOptions };
        }
      } catch {
        finalOptions = { cookie: options };
      }
    } else {
      finalOptions = options;
    }

    this.cookie = finalOptions.cookie || "";
    this.bearer = finalOptions.bearer || "";
    this.userAgent =
      finalOptions.userAgent ||
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";
  }

  private getDeviceId(): string {
    if (!this.deviceId) {
      this.deviceId = crypto.randomUUID();
    }
    return this.deviceId;
  }

  private async fetchHeaders(options?: { jsonContentType?: boolean }) {
    const headers: Record<string, string> = {
      Cookie: this.cookie,
      "User-Agent": this.userAgent,
      Accept: "*/*",
      ...(this.bearer ? { Authorization: `Bearer ${this.bearer}` } : {}),
      Referer: "https://chat.deepseek.com/",
      Origin: "https://chat.deepseek.com",
      "x-client-platform": "web",
      "x-client-version": "2.0.0",
      "x-app-version": "2.0.0",
      "x-client-locale": "zh_CN",
      "x-client-timezone-offset": "28800",
    };
    if (options?.jsonContentType !== false) {
      headers["Content-Type"] = "application/json";
    }
    return headers;
  }

  async init() {
    // Get device ID from settings if not already present
    if (!this.deviceId) {
      try {
        const res = await fetch(
          "https://chat.deepseek.com/api/v0/client/settings?did=&scope=banner",
          {
            headers: await this.fetchHeaders({ jsonContentType: false }),
          },
        );
        if (res.ok) {
          // data is currently unused
          // const data = await res.json();
          // Extract did from headers or data if available
        }
      } catch (error) {
        console.warn("[DeepSeekWebClient] Failed to fetch settings:", error);
      }
    }
  }

  async fetchClientSettings(scope: string): Promise<Record<string, unknown> | null> {
    const url = new URL("https://chat.deepseek.com/api/v0/client/settings");
    url.searchParams.set("did", this.getDeviceId());
    url.searchParams.set("scope", scope);
    const res = await fetch(url, {
      headers: await this.fetchHeaders({ jsonContentType: false }),
    });
    if (!res.ok) {
      return null;
    }
    const json = (await res.json()) as DeepSeekClientSettingsResponse;
    if (json.code !== 0 || json.data?.biz_code !== 0) {
      return null;
    }
    return unwrapDeepSeekSettings(json.data.biz_data?.settings);
  }

  async createPowChallenge(targetPath: string): Promise<DeepSeekPowChallenge> {
    console.log(`[DeepSeekWebClient] Creating PoW challenge for ${targetPath}...`);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);
    try {
      const res = await fetch("https://chat.deepseek.com/api/v0/chat/create_pow_challenge", {
        method: "POST",
        headers: await this.fetchHeaders(),
        body: JSON.stringify({
          target_path: targetPath,
        }),
        signal: controller.signal,
      });

      if (!res.ok) {
        const errorText = await res.text();
        console.error(
          `[DeepSeekWebClient] Failed to create PoW challenge: ${res.status}`,
          errorText,
        );
        throw new Error(`Failed to create PoW challenge: ${res.status} ${errorText}`);
      }
      const json = await res.json();
      console.log(`[DeepSeekWebClient] Challenge received:`, json);
      const challenge =
        json.data?.biz_data?.challenge || json.data?.challenge || json.challenge || json;
      return challenge;
    } finally {
      clearTimeout(timeout);
    }
  }

  private wasmModule: WebAssembly.Instance | null = null;

  private async getWasmInstance() {
    if (this.wasmModule) {
      return this.wasmModule;
    }
    // The Base64 string is quite large, so we use a constant defined outside or load it here.
    // To keep the file clean, I'll use the SHA3_WASM_B64 constant.
    const wasmBuffer = Buffer.from(SHA3_WASM_B64, "base64");
    const { instance } = await WebAssembly.instantiate(wasmBuffer, { wbg: {} });
    this.wasmModule = instance;
    return instance;
  }

  async solvePow(challenge: DeepSeekPowChallenge): Promise<number> {
    const { algorithm, challenge: target, salt, difficulty, expire_at } = challenge;
    console.log(`[DeepSeekWebClient] Solving PoW (${algorithm}, difficulty: ${difficulty})...`);

    if (algorithm === "sha256") {
      const start = Date.now();
      let nonce = 0;
      while (true) {
        const input = salt + target + nonce;
        const hash = crypto.createHash("sha256").update(input).digest("hex");
        let zeroBits = 0;
        for (const char of hash) {
          const val = parseInt(char, 16);
          if (val === 0) {
            zeroBits += 4;
          } else {
            zeroBits += Math.clz32(val) - 28;
            break;
          }
        }
        const targetDifficulty = difficulty > 1000 ? Math.floor(Math.log2(difficulty)) : difficulty;
        if (zeroBits >= targetDifficulty) {
          console.log(
            `[DeepSeekWebClient] SHA256 PoW solved in ${Date.now() - start}ms, nonce: ${nonce}`,
          );
          return nonce;
        }
        nonce++;
        if (nonce > 1000000) {
          throw new Error("SHA256 PoW timeout");
        }
      }
    }

    if (algorithm === "DeepSeekHashV1") {
      const instance = await this.getWasmInstance();
      const exports = instance.exports as unknown as DeepSeekWasmExports;
      const memory = exports.memory;
      const alloc = exports.__wbindgen_export_0;
      const add_to_stack = exports.__wbindgen_add_to_stack_pointer;
      const wasm_solve = exports.wasm_solve;

      const prefix = `${salt}_${expire_at}_`;
      const challengeStr = target;

      const encodeString = (str: string) => {
        const buf = Buffer.from(str, "utf8");
        const ptr = alloc(buf.length, 1);
        new Uint8Array(memory.buffer).set(buf, ptr);
        return [ptr, buf.length];
      };

      const [ptrC, lenC] = encodeString(challengeStr);
      const [ptrP, lenP] = encodeString(prefix);
      const retptr = add_to_stack(-16);

      const start = Date.now();
      console.log(`[DeepSeekWebClient] Calling WASM wasm_solve (difficulty: ${difficulty})...`);
      wasm_solve(retptr, ptrC, lenC, ptrP, lenP, difficulty);
      const end = Date.now();

      const view = new DataView(memory.buffer);
      const status = view.getInt32(retptr, true);
      const answer = view.getFloat64(retptr + 8, true);
      add_to_stack(16);

      if (status === 0) {
        throw new Error("DeepSeekHashV1 failed to find solution");
      }
      console.log(
        `[DeepSeekWebClient] DeepSeekHashV1 solved in ${end - start}ms, answer: ${answer}`,
      );
      return answer;
    }

    throw new Error(`Unsupported PoW algorithm: ${algorithm}`);
  }

  async createChatSession(): Promise<DeepSeekChatSession> {
    const targetPath = "/api/v0/chat_session/create";
    // chat_session/create typically does NOT require PoW or it might fail with INVALID_TARGET_PATH
    const res = await fetch(`https://chat.deepseek.com${targetPath}`, {
      method: "POST",
      headers: await this.fetchHeaders(),
      body: JSON.stringify({ character_id: null }),
    });

    if (!res.ok) {
      const errorText = await res.text();
      console.error(`[DeepSeekWebClient] Failed to create chat session: ${res.status}`, errorText);
      throw new Error(`Failed to create chat session: ${res.status} ${errorText}`);
    }

    const data = (await res.json()) as DeepSeekChatSessionResponse;

    // Check for API-level errors even if HTTP status is 200 OK
    if (data.code !== 0 && data.code !== undefined) {
      throw new Error(
        `Failed to create chat session: ${data.msg || "Unknown error"} (code: ${data.code})`,
      );
    }
    if (data.data && data.data.biz_code !== 0 && data.data.biz_code !== undefined) {
      throw new Error(
        `Failed to create chat session: ${
          data.data.biz_msg || "Unknown error"
        } (biz_code: ${data.data.biz_code})`,
      );
    }

    const bizData = data.data?.biz_data || data.data || data;
    const chatSession = bizData?.chat_session || bizData;
    const sessionId =
      chatSession?.id ||
      chatSession?.chat_session_id ||
      bizData?.id ||
      bizData?.chat_session_id ||
      "";

    if (!sessionId) {
      console.error(
        `[DeepSeekWebClient] Failed to extract chat session ID from response:`,
        JSON.stringify(data),
      );
      throw new Error(`Failed to extract chat_session_id from response: ${JSON.stringify(data)}`);
    }

    console.log(`[DeepSeekWebClient] Chat session created: ${sessionId}`);
    return {
      biz_id: bizData?.biz_id || chatSession?.biz_id || "",
      title: bizData?.title || chatSession?.title || "",
      ...bizData,
      chat_session_id: sessionId,
    };
  }

  async chatCompletions(params: {
    sessionId: string;
    message: string;
    model?: string;
    fileIds?: string[];
    searchEnabled?: boolean;
    preempt?: boolean;
    parentMessageId?: string | number | null;
    signal?: AbortSignal;
  }) {
    const targetPath = "/api/v0/chat/completion";
    const challenge = await this.createPowChallenge(targetPath);
    const answer = await this.solvePow(challenge);
    const powResponse = Buffer.from(
      JSON.stringify({
        ...challenge,
        answer,
        target_path: targetPath,
      }),
    ).toString("base64");

    console.log(
      `[DeepSeekWebClient] Chat completion → session=${params.sessionId} len=${params.message.length}` +
        `\n  head: ${params.message.slice(0, 120).replace(/\n/g, " ")}` +
        `\n  tail: ${params.message.slice(-200).replace(/\n/g, " ")}`,
    );
    const headers = {
      ...(await this.fetchHeaders()),
      "x-ds-pow-response": powResponse,
    };

    console.log(
      `[DeepSeekWebClient] Sending chat completion request to /api/v0/chat/completion...`,
    );
    const res = await fetch(`https://chat.deepseek.com${targetPath}`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        chat_session_id: params.sessionId,
        parent_message_id: params.parentMessageId ?? null,
        model_type: resolveDeepSeekWebModelType(params.model),
        prompt: params.message,
        ref_file_ids: params.fileIds || [],
        thinking_enabled: resolveDeepSeekWebThinkingEnabled(params.model),
        search_enabled: resolveDeepSeekWebSearchEnabled(params.model, params.searchEnabled),
        preempt: params.preempt ?? false,
      }),
      signal: params.signal,
    });

    if (!res.ok) {
      const errorText = await res.text();
      console.error(`[DeepSeekWebClient] Chat completion request failed: ${res.status}`, errorText);
      throw new Error(`Chat completion failed: ${res.status} ${errorText}`);
    }

    console.log(
      `[DeepSeekWebClient] Chat completion response OK (status: ${res.status}). Content-Type: ${res.headers.get("content-type")}`,
    );
    return res.body;
  }

  async uploadFile(fileData: Buffer, fileName: string) {
    const targetPath = "/api/v0/file/upload_file";
    const challenge = await this.createPowChallenge(targetPath);
    const answer = await this.solvePow(challenge);
    const powResponse = Buffer.from(
      JSON.stringify({
        ...challenge,
        answer,
        target_path: targetPath,
      }),
    ).toString("base64");

    const formData = new (globalThis as unknown as { FormData: new () => FormData }).FormData();
    formData.append(
      "file",
      new (
        globalThis as unknown as { Blob: new (p: unknown[], opts?: BlobPropertyBag) => Blob }
      ).Blob([fileData]),
      fileName,
    );
    const headers = await this.fetchHeaders({ jsonContentType: false });

    const res = await fetch(`https://chat.deepseek.com${targetPath}`, {
      method: "POST",
      headers: {
        ...headers,
        "x-ds-pow-response": powResponse,
        "x-file-size": fileData.length.toString(),
      },
      body: formData,
    });

    if (!res.ok) {
      throw new Error(`File upload failed: ${res.status} ${await res.text()}`);
    }

    const data = await res.json();
    const fileId = data.data.biz_data.id;

    // Polling for success
    let attempts = 0;
    while (attempts < 30) {
      const pollRes = await fetch(
        `https://chat.deepseek.com/api/v0/file/fetch_files?file_ids=${fileId}`,
        {
          headers: await this.fetchHeaders({ jsonContentType: false }),
        },
      );
      if (pollRes.ok) {
        const pollData = await pollRes.json();
        const file = pollData.data.biz_data.files[0];
        if (file?.status === "SUCCESS") {
          return fileId;
        }
        if (file?.status === "FAILED") {
          throw new Error(`File parsing failed for ${fileId}`);
        }
      }
      await new Promise((r) => setTimeout(r, 2000));
      attempts++;
    }

    return fileId;
  }

  async discoverModels(): Promise<ModelDefinitionConfig[]> {
    const settings = await this.fetchClientSettings("model").catch((error) => {
      console.warn("[DeepSeekWebClient] Failed to fetch model settings:", error);
      return null;
    });
    const remoteModelConfigs = Array.isArray(settings?.model_configs)
      ? settings.model_configs.map(toDeepSeekRemoteModelConfig).filter((model) => model !== null)
      : [];
    const discoveredModels = buildDeepSeekModelsFromRemoteConfigs(remoteModelConfigs);
    if (discoveredModels.length > 0) {
      return discoveredModels;
    }

    const baseModels: ModelDefinitionConfig[] = [
      {
        id: "deepseek-chat",
        name: "DeepSeek Fast Mode",
        reasoning: false,
        input: ["text", "image"],
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
        maxTokens: 4096,
      },
      {
        id: "deepseek-chat-expert",
        name: "DeepSeek Expert Mode",
        reasoning: false,
        input: ["text"],
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
        maxTokens: 4096,
      },
      {
        id: "deepseek-reasoner",
        name: "DeepSeek Fast Mode + Deep Thinking",
        reasoning: true,
        input: ["text", "image"],
        maxTokens: 4096,
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
      },
      {
        id: "deepseek-reasoner-expert",
        name: "DeepSeek Expert Mode + Deep Thinking",
        reasoning: true,
        input: ["text"],
        maxTokens: 4096,
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
      },
      {
        id: "deepseek-vision",
        name: "DeepSeek Vision Mode",
        reasoning: false,
        input: ["text", "image"],
        maxTokens: 4096,
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
      },
      {
        id: "deepseek-reasoner-vision",
        name: "DeepSeek Vision Mode + Deep Thinking",
        reasoning: true,
        input: ["text", "image"],
        maxTokens: 4096,
        cost: {
          input: 0,
          output: 0,
          cacheRead: 0,
          cacheWrite: 0,
        },
        contextWindow: 64000,
      },
    ];

    const models = [...baseModels];
    for (const m of baseModels) {
      models.push({
        ...m,
        id: `${m.id}-search`,
        name: `${m.name} (Search)`,
      });
    }

    return models;
  }
}
